/// Safetensors loader for Qwen3.5-4B language model weights.
///
/// Loads weights from .safetensors files into typed Rust structs.
/// Uses memmap2 for zero-copy loading where possible.
pub struct SafetensorsLoader {
    /// The model config for shape validation.
    config: ModelConfig,
}

impl SafetensorsLoader {
    /// Create a new loader with the given config.
    pub fn new(config: ModelConfig) -> Self {
        Self { config }
    }

    /// Load model weights from a directory containing safetensors files.
    ///
    /// # Arguments
    /// * `path` — Directory containing model.safetensors (and optionally model-00001-of-NNNNN.safetensors)
    /// * `config` — Model configuration for shape validation
    ///
    /// # Returns
    /// * `Result<ModelWeights>` — Loaded weights or error
    pub fn load_model(path: &Path, config: &ModelConfig) -> Result<ModelWeights> {
        let mut weights = ModelWeights {
            embedding: EmbeddingWeights {
                embed_tokens: WeightTensor {
                    data: Vec::new(),
                    shape: vec![],
                    dtype: TensorDType::F16,
                },
            },
            layers: Vec::new(),
            final_norm: WeightTensor {
                data: Vec::new(),
                shape: vec![],
                dtype: TensorDType::F16,
            },
        };

        // Find all safetensors files in the directory
        let mut files: Vec<PathBuf> = std::fs::read_dir(path)
            .with_context(|| format!("Failed to read safetensors directory: {:?}", path))?
            .filter_map(|e| e.ok())
            .filter(|e| e.path().extension().map_or(false, |ext| ext == "safetensors"))
            .collect();

        files.sort();

        if files.is_empty() {
            return Err(anyhow::anyhow!(
                "No .safetensors files found in {:?}",
                path
            ));
        }

        // Load all shards
        for file in &files {
            let file_path = file.path();
            tracing::debug!("Loading safetensors shard: {:?}", file_path.display());

            let (data, dtype) = Self::load_shard(&file_path)?;
            Self::extract_weights(&data, &dtype, &mut weights)?;
        }

        // Validate shapes
        Self::validate_shapes(&weights)?;

        Ok(weights)
    }

